  const sessionKey = String(event.sessionKey ?? ctx.sessionKey ?? '');
  const parts = sessionKey.split(':');
  const agentIdx = parts.indexOf('agent');

  let channel = String(ctx.channelId || '').toLowerCase();
  if (!channel && agentIdx >= 0 && parts[agentIdx + 2]) channel = String(parts[agentIdx + 2]).toLowerCase();
  if (channel !== 'line') return null;

  const accountId = agentIdx >= 0 && parts[agentIdx + 1] ? parts[agentIdx + 1] : null;
  if (!accountId) return null;

  let userId = String(
    ctx.senderId ?? ctx.conversationId ?? ctx.from ?? ctx.to ??
    event.from ?? event.senderId ?? ctx.chatId ?? ''
  );
  userId = userId.replace(/^(telegram|line|whatsapp|discord|sms):/i, '');
  if (!userId) userId = parts[parts.length - 1] || '';
  userId = userId.toLowerCase();
  if (!userId) return null;

  return { accountId, userId };
